module protocol::adl;

use math::float::Decimal;
use std::type_name::Self;
use protocol::generic_store::{Self, GenericCoinTypeStorage};

use protocol::error;
use sui::clock::Clock;
use protocol::value::clock_now;
use std::type_name::TypeName;
use sui::table::Table;
use sui::event::emit;
use std::option::none;
use std::option::some;

const SECONDS_IN_A_DAY: u64 = 86400;
const SECONDS_IN_AN_HOUR: u64 = 3600;

public struct ADLDeactivated has copy, drop {
    is_borrow: bool,
    market: TypeName,
    coin: TypeName,
    emode_group_id: Option<u8>,
    params: TimeLock<DeleverageParams>,
}

public struct TimeLock<T: copy + drop + store> has copy, drop, store {
    inner: T,
    timestamp: u64,
}

public struct DeleverageParams has copy, drop, store {
    target_amount: u64,

    liquidation_factor_base: Decimal,
    liquidation_factor_hourly_drop: Decimal,

    liquidation_incentive_base: Decimal,
    liquidation_incentive_daily_penalty: Decimal,

    close_factor: Decimal,
}

public struct AutoDeleverageRegistry has store {
    collaterals: GenericCoinTypeStorage<TimeLock<DeleverageParams>>,
    borrows: Table<u8, GenericCoinTypeStorage<TimeLock<DeleverageParams>>>,
}

public(package) fun new_auto_deleverage_params(
    target_amount: u64,
    liquidation_factor_base: Decimal,
    liquidation_factor_hourly_drop: Decimal,
    liquidation_incentive_base: Decimal,
    liquidation_incentive_daily_penalty: Decimal,
    close_factor: Decimal,
): DeleverageParams {
    DeleverageParams {
        target_amount,
        liquidation_factor_base,
        liquidation_factor_hourly_drop,
        liquidation_incentive_base,
        liquidation_incentive_daily_penalty,
        close_factor,
    }
}

public(package) fun new_auto_deleverage_registry(ctx: &mut TxContext): AutoDeleverageRegistry {
    AutoDeleverageRegistry {
        collaterals: generic_store::new(ctx),
        borrows: sui::table::new(ctx)
    }
}

public(package) fun enable_collateral_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    params: DeleverageParams,
    activation_timestamp: u64
) {
    let coin_type = type_name::with_defining_ids<CoinType>();
    assert!(!self.collaterals.supports_type(coin_type), error::adl_already_has_coin());

    let timelock = TimeLock { inner: params, timestamp: activation_timestamp };
    self.collaterals.store<TimeLock<DeleverageParams>, CoinType>(timelock);
}

public(package) fun enable_debt_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    emode_group_id: u8,
    params: DeleverageParams,
    activation_timestamp: u64,
    ctx: &mut TxContext,
) {
    if(!self.borrows.contains(emode_group_id)) {
        self.borrows.add(emode_group_id, generic_store::new(ctx));
    };

    let coin_borrows = self.borrows.borrow_mut(emode_group_id);

    let coin_type = type_name::with_defining_ids<CoinType>();
    assert!(!coin_borrows.supports_type(coin_type), error::adl_already_has_coin());

    let timelock = TimeLock { inner: params, timestamp: activation_timestamp };
    coin_borrows.store<TimeLock<DeleverageParams>, CoinType>(timelock);
}

public(package) fun try_stop_collateral_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    market: TypeName,
    current_value: u64,
) {
    let coin_type = type_name::with_defining_ids<CoinType>();

    if (!self.collaterals.supports_type(coin_type)) return;

    let t = self.collaterals.load_by_type(coin_type);
    if (t.inner.target_amount < current_value) return;

    self.stop_collateral_deleverage<CoinType>(market);
}

public(package) fun stop_collateral_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    market: TypeName,
) {
    // current value is equal to less than limit  
    let params = self.collaterals.remove<TimeLock<DeleverageParams>, CoinType>();
    emit(ADLDeactivated { is_borrow: false, market, coin: type_name::with_defining_ids<CoinType>(), params, emode_group_id: none() });
}

public(package) fun try_stop_borrow_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    market: TypeName,
    emode_group_id: u8,
    current_value: u64,
) {
    if(!self.borrows.contains(emode_group_id)) return;

    let coin_borrows = self.borrows.borrow(emode_group_id);

    let coin_type = type_name::with_defining_ids<CoinType>();
    if (!coin_borrows.supports_type(coin_type)) return;

    let t = coin_borrows.load_by_type(coin_type);
    if (t.inner.target_amount < current_value) return;

    self.stop_borrow_deleverage<CoinType>(market, emode_group_id);
}

public(package) fun stop_borrow_deleverage<CoinType>(
    self: &mut AutoDeleverageRegistry,
    market: TypeName,
    emode_group_id: u8,
) {
    let coin_borrows = self.borrows.borrow_mut(emode_group_id);
    let params = coin_borrows.remove<TimeLock<DeleverageParams>, CoinType>();
    emit(ADLDeactivated { is_borrow: true, market, coin: type_name::with_defining_ids<CoinType>(), params, emode_group_id: some(emode_group_id) });
}

public(package) fun get_collateral_deleverage(
    self: &AutoDeleverageRegistry,
    coin_type: TypeName,
): &TimeLock<DeleverageParams> {
    assert!(self.collaterals.supports_type(coin_type), error::adl_no_coin());
    self.collaterals.load_by_type<TimeLock<DeleverageParams>>(coin_type)
}

public(package) fun get_borrow_deleverage(
    self: &AutoDeleverageRegistry,
    coin_type: TypeName,
    emode_group_id: u8,
): &TimeLock<DeleverageParams> {
    assert!(self.borrows.contains(emode_group_id), error::adl_emode_group_not_found());

    let coin_borrows = self.borrows.borrow(emode_group_id);
    assert!(coin_borrows.supports_type(coin_type), error::adl_no_coin());

    coin_borrows.load_by_type<TimeLock<DeleverageParams>>(coin_type)
}

public(package) fun get_secs_since_activation<T: copy + drop + store>(self: &TimeLock<T>, clock: &Clock): u64 {
    let now = clock_now(clock);
    assert!(self.timestamp <= now, error::adl_not_activated_by_time());

    now - self.timestamp
}

public(package) fun inner<T: copy + drop + store>(self: &TimeLock<T>): &T {
    &self.inner
}

// public methods

public fun close_factor(self: &DeleverageParams): Decimal { self.close_factor }
public fun target_amount(self: &DeleverageParams): u64 { self.target_amount }

public fun liquidation_factor_base(self: &DeleverageParams): Decimal { self.liquidation_factor_base }
public fun liquidation_factor_hourly_drop(self: &DeleverageParams): Decimal { self.liquidation_factor_hourly_drop }
public fun liquidation_incentive_base(self: &DeleverageParams): Decimal { self.liquidation_incentive_base }
public fun liquidation_incentive_daily_penalty(self: &DeleverageParams): Decimal { self.liquidation_incentive_daily_penalty }

public fun liquidation_incentive(self: &DeleverageParams, secs_since_activation: u64): Decimal { 
    let days = secs_since_activation / SECONDS_IN_A_DAY;

    let add_on = self.liquidation_incentive_daily_penalty.mul_u64(days);
    self.liquidation_incentive_base.add(add_on)
}

public fun liquidation_ltv(self: &DeleverageParams, secs_since_activation: u64): Decimal { 
    let hours = secs_since_activation / SECONDS_IN_AN_HOUR;

    let reduction = self.liquidation_factor_hourly_drop.mul_u64(hours);
    self.liquidation_factor_base.saturating_sub(reduction)
}

public(package) fun ensure_limit_breached(self: &DeleverageParams, current_value: u64) {
    assert!(self.target_amount < current_value, error::adl_within_limit());
}

