        float::from_quotient(75, 100),
        float::from_quotient(10, 100),
        500000000,
        float::from_quotient(120, 100),
        float::from_quotient(2, 1000),
        limiter::create_new_limiter_change(3000000000, 86400, 3600),
        limiter::create_new_limiter_change(1000000000, 86400, 3600),
    );

    registry.support_asset<TestCoinA>(group1, params_a, scenario.ctx());
    registry.support_asset<TestCoinB>(group1, params_b, scenario.ctx());

    // List assets
    let assets = registry.list_assets(group1, 1000);
    assert!(assets.length() == 2, 0);

    scenario.end();
    std::unit_test::destroy(registry);
}

